package org.jquantlib.math.randomnumbers;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Base64;

/**
 * Joe-Kuo D7 free direction-integer initializers for {@link SobolRsg}.
 *
 * <p>Faithful Java port of the C++ {@code JoeKuoD7initializers} table from
 * {@code ql/math/randomnumbers/sobolrsg.cpp} (v1.42.1,
 * {@code 099987f0ca2c11c505dc4348cdb9ce01a598e1e5}), covering 1899
 * dimensions. The table is a publication by Stephen Joe and Frances Kuo
 * of free direction integers calibrated for "Property A" and improved
 * two-dimensional projections, distributed under a BSD-style license
 * documented at <http://web.maths.unsw.edu.au/~fkuo/sobol/>.
 *
 * <p>Reference: S. Joe and F. Y. Kuo, "Constructing Sobol sequences with
 * better two-dimensional projections", preprint, 22 Nov 2007.
 *
 * <p>Layout: {@link #INITIALIZERS}{@code [k]} stores the non-zero free
 * direction integers for dimension {@code k+1} (i.e. {@code [0]} ==
 * dim&nbsp;1 == {@code {1}}, ..., {@code [1898]} == dim&nbsp;1899). The
 * C++ source terminates each dim with a sentinel {@code 0}; that
 * sentinel is omitted in the Java arrays (use {@code .length}).
 *
 * <p><strong>Encoding.</strong> The raw integer table is ~26&nbsp;000
 * values; emitting them as Java literals breaks the JVM 64&nbsp;KiB
 * {@code <clinit>} byte-code limit. The table is instead held as a
 * Base64-encoded blob (little-endian {@code uint16} stream:
 * {@code [rowLen,v0,...,v(rowLen-1)]} per row) and decoded once at
 * class-load time. The decoded values are bit-for-bit identical to the
 * C++ source.
 *
 * <p>Phase 5e.5b-CFC-d-268.
 */
final class JoeKuoD7Initializers {

    private JoeKuoD7Initializers() {
        // utility holder
    }

    /**
     * Number of dimensions in the table (matches the C++
     * {@code JoeKuoD7initializers[1899]}).
     */
    static final int N_DIMENSIONS = 1899;

    /**
     * Free direction-integer initializers for dimensions 1..1899
     * (indexed 0..1898). Lengths vary 1..15.
     */
    static final int[][] INITIALIZERS;

    /** Base64-encoded little-endian uint16 stream of the table. */
    private static final String[] BLOB = {
            "",
            "",
    };

    static {
        final StringBuilder sb = new StringBuilder(BLOB.length * 60000);
        for (final String s : BLOB) {
            sb.append(s);
        }
        final byte[] raw = Base64.getDecoder().decode(sb.toString());
        final ByteBuffer bb = ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);
        INITIALIZERS = new int[N_DIMENSIONS][];
        for (int k = 0; k < N_DIMENSIONS; k++) {
            final int rowLen = bb.getShort() & 0xFFFF;
            final int[] row = new int[rowLen];
            for (int j = 0; j < rowLen; j++) {
                row[j] = bb.getShort() & 0xFFFF;
            }
            INITIALIZERS[k] = row;
        }
    }
}
